{"actions":[{"tool":"write_file","path":"core.py","content":"import math


def validate(rows, y, weights, n):
    try:
        if isinstance(n, bool) or not isinstance(n, int) or n < 1:
            raise ValueError('inputs')
        if len(rows) != len(y) or len(y) != len(weights):
            raise ValueError('inputs')
        for weight in weights:
            if not math.isfinite(weight) or weight < 0:
                raise ValueError('inputs')
        for row, label in zip(rows, y):
            if not row or isinstance(label, bool) or not isinstance(label, int) or not 0 <= label < len(row):
                raise ValueError('probabilities')
            if any(not math.isfinite(value) or value < 0 or value > 1 for value in row):
                raise ValueError('probabilities')
            if abs(sum(row) - 1) > 1e-8:
                raise ValueError('probabilities')
    except (TypeError, OverflowError):
        raise ValueError('inputs') from None


def bins(rows, y, weights, n):
    validate(rows, y, weights, n)
    accum = [[0.0, 0.0, 0.0] for _ in range(n)]
    for row, label, weight in zip(rows, y, weights):
        # max returns the first index on ties.
        prediction = max(range(len(row)), key=lambda i: row[i])
        confidence = row[prediction]
        slot = min(int(confidence * n), n - 1)
        accum[slot][0] += weight
        accum[slot][1] += weight * (prediction == label)
        accum[slot][2] += weight * confidence
    return [
        {
            'weight': weight,
            'accuracy': correct / weight if weight else 0.0,
            'confidence': confidence / weight if weight else 0.0,
        }
        for weight, correct, confidence in accum
    ]


def brier(rows, y, weights):
    # The bin count is irrelevant to Brier, so perform the shared validation directly.
    validate(rows, y, weights, 1)
    total = sum(weights)
    if total == 0:
        return 0.0
    return sum(
        weight * sum((value - (index == label)) ** 2 for index, value in enumerate(row))
        for row, label, weight in zip(rows, y, weights)
    ) / total
